def rr(p):
 with p.open() as f:return list(csv.DictReader(f))
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def link(p,label=None):return '<a href="'+html.escape(os.path.relpath(p,R),quote=True)+'">'+html.escape(label or p.name)+'</a>'
def table(rows,fields):
 return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(label)+'</th>' for _,label in fields)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(row.get(k,'')))+'</td>' for k,_ in fields)+'</tr>' for row in rows)+'</tbody></table></div>'
def lines(g):
 if g.geom_type=='Polygon':return [np.asarray(g.exterior.coords)]
 if g.geom_type in ['LineString','LinearRing']:return [np.asarray(g.coords)]
 return [l for sub in g.geoms for l in lines(sub)]
