 summary={'human_decision':'MILI-D-20261016-021','build_status':'Technically verified regional normal candidate graphs; complete operational network not yet admitted','source':'Geofabrik Kanto 2026-10-15, ODbL OpenStreetMap contributors','surface':s,'rail_access':a,'road_extent_checks':extent,'rail_extent_checks':railext,'routing_probe_status_counts':dict(statuses),'routing_probe_extent_summary':probecompare,'technical_validation':v['technical_checks_passed'],'population_uncertainty_retained_by_reference':True,'stranded_people_computed':False,'new_hydraulic_runs':False};dump(R/'summary.json',summary)
 styles='body{font:16px/1.65 system-ui,sans-serif;background:#f4f7fa;color:#21394a;max-width:1250px;margin:34px auto;padding:0 24px}h1{font-size:32px;line-height:1.2}h2{font-size:23px;margin-top:34px}.lead{font-size:19px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:#e5eff0;border-radius:8px;padding:16px}.card b{font-size:28px}.notice{background:#fff1d9;border-left:4px solid #c4852c;padding:16px}.ok{background:#e4f0e9;border-left:4px solid #44846c;padding:16px}.scroll{overflow:auto}table{background:white;border-collapse:collapse;width:100%;font-size:13px}th,td{border:1px solid #dae2e8;padding:9px;text-align:left;vertical-align:top}th{background:#e5eef3}img{display:block;width:100%;background:white;margin:22px 0}a{color:#126c82}.small{font-size:13px;color:#506779}code{font-size:13px}@media(max-width:700px){.cards{grid-template-columns:repeat(2,1fr)}}'
 doc='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Three-ward normal transport network</title><style>'+styles+'</style><h1>Three-ward normal transport network</h1><p class="lead">Regional walking, motorcar and rail/access candidate graphs are now built and technically checked. Source-ID connectivity, mode permissions, relative levels, ordered rail stops and conditional station circulation remain explicit. A complete legal and operational multimodal baseline is still awaiting qualification.</p>'
 doc+='<div class="cards">'+''.join('<div class="card"><b>'+value+'</b><br>'+label+'</div>' for value,label in [(f"{s['surface_ways_retained']:,}",'retained regional highway ways'),(f"{a['core_entrances_with_source_walk_path']}/{a['entrances_inside_core']}",'core entrances with qualified native walk access'),(str(v['rule_selfcheck_count']),'routing / parsing checks passed'),('0','new hydraulic runs / people assigned')])+'</div>'
 doc+='<p class="notice">Disconnected source components, unmatched station identities and withheld entrances are QA gaps, not observed closures or flood-caused islands. Fractions of graph nodes are not fractions of residents. Station stop occurrences repeat by service and direction; they are not counts of physical stations.</p><img src="normal_network_regional_overview.png" alt="Regional normal network coverage and acquisition halo comparison">'
 doc+='<h2>What changed from the previous inventory</h2>'+table([{'layer':'Road permissions','implemented':'Native source node/way graph; mode-specific access hierarchy, one-way rules, node barriers, private/destination through-access exclusions and conditional/opening-time unknowns.','limit':'Class defaults are declared modeling assumptions, not certification of Japanese legal access. Unknown-open sensitivity never overrides explicit denials.'},{'layer':'Elevated / underground','implemented':'Native ID + relative floor/layer/structure nodes. Source-supported bridge/tunnel endpoints and stairs/lifts can connect; no planar noding or proximity join.','limit':'Relative floor/layer is not absolute deck/rail/inlet height. Shared-node conflicts remain held.'},{'layer':'Motorcar turns','implemented':str(s['supported_turn_rules'])+' supported base rules; via-node/via-way turn memory, source transition locations, and grade portals that preserve incoming way history.','limit':str(s['conditional_turn_rules'])+' conditional rules have no selected departure clock. Unqualified from-ways are withheld from conservative driving; plain SCCs ignore turn memory.'},{'layer':'Station / interchange','implemented':'Native-ID entrance-to-walk links; explicit source platform membership and same stop_area; floor conflicts held. Separate graph adds exact-operator, same-area internal circulation assumptions.','limit':'No nearest-station edges, generic cross-operator joins or invented internal corridors. Paid-area, gate and transfer opening details remain incomplete.'},{'layer':'Rail / JR service','implemented':'Source-ordered stop roles and consecutive forward service arcs; no coordinate sorting, missing-stop leapfrogging or guessed reverse links. N02 independently audits identities and geometry.','limit':'No verified departure calendar, timetable, capacity or complete through-running inventory. Legal N02 corridors are not operating-service definitions.'}], [('layer','Layer'),('implemented','Built and checked'),('limit','Remaining interpretation limit')])
 doc+='<h2>Extent and bounded route checks</h2><p>The road graph uses whole source edges inside a 10 km core halo. Restricting it to 5 km loses no core nodes and the tests below show whether core components merge after expansion. The rail inventory uses 20 km; its 10 km comparison holds the walking graph fixed. These are structural extent checks, not a proof that every future destination or detour is covered.</p>'+table(extent,[('mode','Mode'),('partition_kind','Topology'),('core_groups_5km','Core groups, 5 km'),('core_groups_10km','Core groups, 10 km'),('core_groups_merged_by_outer_5_to_10km','Groups merged'),('core_nodes_missing_in_5km','Missing core nodes')])+table(railext,[('branch','Rail access branch'),('partition_kind','Topology'),('core_groups_with_10km_rail','Core groups, 10 km rail'),('core_groups_with_20km_rail','Core groups, 20 km rail'),('core_groups_merged_by_outer_rail','Groups merged')])
 doc+='<p>Three synthetic road QA origins, one per ward, are compared with six external station vicinities, without adding station entrance links or assigning people to any origin. Walk and turn-aware motorcar searches use the same anchors at both road extents. Distances are lengths, not journey times. Conditional turns are unresolved in the base probe; a hit to the state budget means unknown, never unreachable.</p>'+table(probecompare,[('mode','Mode'),('OD_pairs','OD pairs'),('both_extents_found','Resolved at both extents'),('maximum_shortening_by_10km_m','Maximum shorter route at 10 km (m)'),('OD_pairs_without_paired_resolved_result','Unpaired / unknown')])+'<p>'+link(R/'routing_probe_checks.csv','All routing probe results')+' · '+link(R/'routing_probe_anchors.csv','QA anchor audit')+'</p>'
 doc+='<img src="normal_network_core_quality.png" alt="Three ward held grade-conflict and station entrance coverage audit"><h2>Station access and interchange qualification</h2><p>'+str(a['core_entrances_with_declared_station_area'])+' of '+str(a['entrances_inside_core'])+' mapped core entrances declare a source station-area membership. Membership alone creates no source-path corridor. Only '+str(a['core_rail_stop_occurrences_with_source_boarding'])+' of '+str(a['core_rail_stop_occurrences'])+' core source stop occurrences have a qualified source platform/walk link; the separately labeled internal-access assumption reaches '+str(a['core_rail_stop_occurrences_with_conditional_access'])+'. These counts indicate source evidence coverage, not actual station accessibility or closure.</p>'+table(opcoverage,[('operator_class','Source operator class'),('core_source_stop_occurrences','Core stop occurrences'),('with_source_platform_access','Source platform access'),('with_conditional_station_access','Including internal-access assumptions')])
 reach=rr(R/'multimodal_directional_reachability.csv');doc+='<h3>Directional potential-service check</h3><p>From each synthetic ward road origin, directed graph traversal checks outward access to core rail stop occurrences and the ability to return. A train may reach a stop even when no local entrance is mapped; these counts do not certify local station entry. Timetables remain unverified. The table shows one origin; the complete file retains all three.</p>'+table([x for x in reach if x['origin_ward']=='Chiyoda'],[('branch','Access branch'),('operator_class','Source operator class'),('core_stop_occurrences','Core stop occurrences'),('reachable_from_road_origin','Outward reachable'),('can_return_to_road_origin','Return reachable'),('reachable_both_directions','Both directions')])+'<p>'+link(R/'multimodal_directional_reachability.csv')+'</p>'
 doc+='<p>Strict name/operator/geometry matching of official N02 station-line records to OSM station areas yields '+str(a['official_core_identity_match_status'].get('name_operator_geometry_unique',0))+' unique matches, '+str(a['official_core_identity_match_status'].get('ambiguous',0))+' ambiguous and '+str(a['official_core_identity_match_status'].get('unmatched',0))+' unmatched records. This deliberately narrow identity check is incomplete; unmatched records do not mean missing physical stations. Operator adapters for smaller operators are not qualified. No identity match automatically creates a transfer.</p><p>'+link(P/'official_station_identity_audit.csv')+' · '+link(R/'official_identity_by_operator.csv')+' · '+link(P/'held_station_access_floor_conflicts.csv')+'</p>'
 doc+='<h2>Priority connection audit</h2>'+table(gaps,[('scope','Scope'),('issue','Issue'),('count','Records / candidates'),('treatment','Treatment')])
 doc+='<p>'+str(s['planar_crossing_audit'].get('different_grade_crossing_kept_separate',0))+' core planar crossings with different source grade keys remain separate. This is an avoided geometric-join opportunity, not proof that every crossing was a previously wrong junction. Unjoined same-grade crossings and nearby endpoints can also be legitimate separations.</p><h2>Population and hydraulic interfaces remain protected</h2><p>The 4,746 official census basic units retain their 2020 resident baseline of 496,345. Both prior delivery manifests pass hash verification. No residents were assigned to a graph component or centroid; the building allocation uncertainties remain referenced without rescaling their absolute mesh-based bounds onto official block totals. A unit intersecting several network components needs a qualified allocation or joint bounds before any population consequence calculation.</p><p>No new flood simulation, training or sealed-test access occurred. This normal baseline does not yet apply closure depths. A later flood join must treat surface roads, elevated decks, underground links and entrances separately, and distinguish entrance failure, station non-stop service and rail-section shutdown.</p>'
 doc+='<h2>What to do next</h2><p>Prioritize batch qualification of station internal circulation, paid gates, cross-line transfers and service identities, then source-grade/turn gaps that change core normal reachability. Preserve source-supported and assumed connections as separate evidence tiers. Add polygon-area walking and destination-access arrival handling before treating absent linear access as actual isolation. Fix these normal-network uncertainties before attributing new disconnections to rain.</p><h2>Validation and reproducible products</h2><p class="ok">Archive MD5 verified; source SHA-256 bound; '+str(v['rule_selfcheck_count'])+' parsing/routing self-checks passed; three independent OSM API coordinate spot checks agree with the PBF decoder. All graph indices and lengths pass; grade portals retain native IDs; rail service edges retain consecutive source order. The coordinate checks are limited parser checks, not topographic or legal-access validation.</p>'
 productlinks=[P/'network_contract.json',P/'network_admission_policy.json',P/'population_uncertainty_sidecar.json',P/'source_acquisition_manifest.json',R/'validation.json',R/'summary.json',P/'walk_conservative_graph.npz',P/'drive_conservative_graph.npz',P/'source_path_multimodal_graph.npz',P/'conditional_internal_multimodal_graph.npz',P/'surface_physical_edges.jsonl.gz',P/'supported_motorcar_restrictions.json',P/'conditional_motorcar_restrictions.json',R/'delivery_manifest.json']
 doc+='<ul>'+''.join('<li>'+link(p)+'</li>' for p in productlinks)+'</ul><h2>Source dates and provenance</h2><p>OSM fixed Kanto extract: replication timestamp 2026-10-15 20:21 UTC; retrieved 2026-10-16. This is an edit-snapshot date, not a uniform survey date or proof of current opening. Official N02 reference: 2025-12-31, released 2026-04. Older official walking datasets and PLATEAU access candidates remain preserved context; they were not blindly joined into this graph.</p><p><a href="https://download.geofabrik.de/asia/japan/kanto.html">Geofabrik Kanto</a> · © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors, ODbL 1.0</a> · <a href="https://wiki.openstreetmap.org/wiki/Key:access">Access tagging</a> · <a href="https://wiki.openstreetmap.org/wiki/Key:oneway">One-way tagging</a> · <a href="https://wiki.openstreetmap.org/wiki/Relation:restriction">Turn restrictions</a> · <a href="https://wiki.openstreetmap.org/wiki/Key:layer">Relative layer</a> · <a href="https://wiki.openstreetmap.org/wiki/Relation:route">Ordered route relations</a> · <a href="https://wiki.openstreetmap.org/wiki/Tag:public_transport%3Dstop_area">Station-area semantics</a> · <a href="https://nlftp.mlit.go.jp/ksj/gml/datalist/KsjTmplt-N02-2025.html">Official N02</a></p><p class="small">Human research decision MILI-D-20261016-021. Normal-source-network audit only; population uncertainty retained.</p></html>'
 (R/'review.html').write_text(doc)
 # Bind all new products and scripts without rewriting frozen delivery files.
 scripts=[ROOT/'src/preprocessing'/x for x in ['extract_normal_transport_osm_v1.py','normal_transport_rules_v1.py','build_normal_surface_network_v1.py','build_normal_rail_access_v1.py']]+[Path(__file__).resolve(),ROOT/'src/analyses/audit_normal_transport_network_v1.py']
 products=sorted([p for parent in [P,R] for p in parent.rglob('*') if p.is_file() and p.name not in ['delivery_manifest.json','delivery_validation.json']])
 def item(p):return {'file':str(p.relative_to(ROOT)),'bytes':p.stat().st_size,'sha256':sha(p)}
 manifest={'human_decision':'MILI-D-20261016-021','products':[item(p) for p in products],'scripts':[item(p) for p in scripts],'prior_inputs':v['population_and_framework_manifests'],'source_license':'ODbL 1.0, OpenStreetMap contributors; Geofabrik extract','frozen_population_intervals_unchanged':True,'new_hydraulics':False,'stranded_people':False,'training':False,'sealed_responses_opened':False};dump(R/'delivery_manifest.json',manifest)
 from html.parser import HTMLParser
 class Links(HTMLParser):
  def __init__(self):super().__init__();self.local=[]
  def handle_starttag(self,tag,attrs):
   for k,val in attrs:
    if k in ['src','href'] and val and not val.startswith(('http:','https:','#','data:')):self.local.append(val)
 parser=Links();parser.feed(doc);missing=[x for x in parser.local if not (R/x).exists()];assert not missing,missing
